<h1>روابط و فرادادهٔ مرشد</h1><p class="notice">مالکیت تجربه، موضوع‌ها، مسئله‌ها و مشاوره‌ها از اطلاعات اصلی سامانه خوانده می‌شوند. این بخش برای ثبت و بررسی رابطه‌های معنایی تازه است؛ اطلاعات خصوصی مخاطبان وارد شبکهٔ عمومی نمی‌شود.</p>
<section class="card section"><h2>پیشنهاد یک رابطه</h2><?= $this->start('/knowledge/propose') ?><label>معنای ارتباط<select name="relation_type"><?php foreach(['ISSUE_IN_TOPIC'=>'مسئله در یک موضوع','TOPIC_PARENT_OF'=>'موضوع، بالادست موضوع دیگر','ISSUE_SUBISSUE_OF'=>'مسئله، زیرمسئلهٔ مسئله دیگر','ISSUE_RELATED_TO_ISSUE'=>'دو مسئلهٔ مرتبط','EXPERIENCE_RELATED_TO_EXPERIENCE'=>'دو تجربهٔ مرتبط'] as $key=>$label): ?><option value="<?= $key ?>"><?= $label ?></option><?php endforeach; ?></select></label><?php foreach(['from_id'=>'از موجودیت','to_id'=>'به موجودیت'] as $key=>$label): ?><label><?= $label ?><select name="<?= $key ?>"><?php foreach($terms as $t): ?><option value="<?= $this->h($t['id']) ?>"><?= $t['kind']==='topic'?'موضوع':'مسئله' ?> · <?= $this->h($t['title']) ?></option><?php endforeach; ?><?php foreach($experiences as $e): ?><option value="<?= $this->h($e['id']) ?>">تجربه · <?= $this->h($e['title']) ?></option><?php endforeach; ?></select></label><?php endforeach; ?><label>منشأ<select name="origin"><option value="admin">بررسی مدیر</option><option value="import">ورود داده</option><option value="ai">پیشنهاد هوش مصنوعی، نیازمند بررسی</option><option value="mentor">گزارش مرشد</option><option value="system">دادهٔ سامانه</option></select></label><label>دسترسی<select name="visibility"><option value="private">خصوصی</option><option value="public">عمومی پس از تأیید</option></select></label><?= $this->field('reason','دلیل ارتباط','text','',true,1000) ?><?= $this->field('evidence','ارجاع مدرک، بدون متن محرمانه','text','',false,500) ?><button>ثبت برای بررسی</button></form></section>
<section class="card section"><h2>بررسی ارتباطات</h2><?php foreach($relations as $r): ?><details class="section"><summary><?= $this->h($r['relation_type'].' · '.$r['origin'].' · '.$r['status']) ?></summary><p><?= $this->h($r['reason']) ?></p><p class="small"><?= $this->h($r['from_id'].' ← '.$r['to_id']) ?></p><?= $this->start('/knowledge/review') ?><input type="hidden" name="id" value="<?= $this->h($r['id']) ?>"><input type="hidden" name="revision" value="<?= (int)$r['revision'] ?>"><label>تصمیم<select name="status"><option value="approved">تأیید</option><option value="rejected">رد</option><option value="revoked">لغو تأیید</option></select></label><button>ثبت تصمیم</button></form></details><?php endforeach; ?><?php if(!$relations): ?><p class="muted">رابطهٔ پیشنهادی ثبت نشده است.</p><?php endif; ?></section>
<div class="grid2 section"><section class="card"><h2>نام‌های هم‌معنا</h2><?= $this->start('/knowledge/aliases') ?><label>طبقه‌بندی<select name="term_id"><?php foreach($terms as $t): ?><option value="<?= $this->h($t['id']) ?>"><?= $this->h($t['title']) ?></option><?php endforeach; ?></select></label><label>نام‌های جایگزین، هر نام در یک خط<textarea name="aliases" maxlength="2400"></textarea></label><button>ذخیرهٔ نام‌ها</button></form></section><section class="card"><h2>ادغام طبقه‌بندی تکراری</h2><p>فقط موضوع با موضوع یا مسئله با مسئله ادغام می‌شود؛ شناسه‌های تاریخی حفظ می‌شوند.</p><?= $this->start('/knowledge/merge') ?><?php foreach(['from'=>'مبدأ تکراری','into'=>'مقصد'] as $key=>$label): ?><label><?= $label ?><select name="<?= $key ?>"><?php foreach($terms as $t): ?><option value="<?= $this->h($t['id']) ?>"><?= $this->h($t['title']) ?></option><?php endforeach; ?></select></label><?php endforeach; ?><button>ادغام با حفظ تاریخچه</button></form></section></div>
<section class="card section"><h2>ثبت شناسه‌های موجود، بدون کپی روابط</h2><p class="muted">پیش‌نمایش: <?= $this->number(array_sum($backfill['counts'])) ?> موجودیت. اجرای دوباره رکورد تکراری ایجاد نمی‌کند.</p><?= $this->start('/knowledge/backfill') ?><button>تکمیل فهرست شناسه‌ها</button></form></section>
<?php if(($this->actor['admin_role']??'')==='system_admin'): ?><section class="card section"><h2>سیاست رویدادهای خصوصی تعامل</h2><p>ثبت رویدادها پیش‌فرض خاموش است. متن جست‌وجو، شرح نیاز مشاوره، پیام، شماره تماس و نشانی اینترنتی دستگاه ذخیره نمی‌شود. پیش از فعال‌سازی، مدت نگهداری را مطابق سیاست مصوب سامانه تعیین کنید.</p><?= $this->start('/knowledge/policy') ?><label>مدت نگهداری به روز<input type="number" name="retention_days" min="1" max="3650" value="<?= $this->h($eventPolicy['retention_days']??'') ?>"></label><label class="check"><input type="checkbox" name="approved" value="1">سیاست نگهداری و اطلاع‌رسانی به کاربران تأیید شده است</label><label class="check"><input type="checkbox" name="enabled" value="1" <?= $eventPolicy['enabled']?'checked':'' ?>>فعال‌سازی ثبت رویدادهای مجاز</label><button>ذخیرهٔ سیاست</button></form></section><?php endif; ?>
